{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.b2b_insights AS WITH inv AS ( SELECT REGEXP_REPLACE(addlitemcode, \'-[^-]+$\', \'\') AS sku_group, SUM(stock_qty) AS inventory_in_hand, SUM(carton_stock) AS carton_stock, max(lot_pur_date) as purchase_date FROM snitch_db.maplemonk.logic_virtual_b2b_ho_get_stock_in_hand WHERE date = CURRENT_DATE - 1 AND branch_name LIKE \'%B2B%\' GROUP BY 1 ), sales AS ( SELECT order_date, marketplace_mapped, branch_code, source, order_name, account_name, sku_group, order_timestamp, suborder_quantity, selling_price, mrp, dispatch_date, category FROM snitch_db.maplemonk.store_fact_items_offline WHERE branch_code = 32 AND COALESCE(suborder_quantity, 0) > 0 AND COALESCE(selling_price, 0) > 0 ), sales_agg AS ( SELECT sku_group, order_date, marketplace_mapped, branch_code, source, order_name, account_name, order_timestamp, mrp, dispatch_date, category, SUM(suborder_quantity) AS total_qty, SUM(selling_price) AS total_sales_value FROM sales GROUP BY sku_group, order_date, marketplace_mapped, branch_code, source, order_name, account_name, order_timestamp, mrp, dispatch_date, category ), sales_30d AS ( SELECT sku_group, SUM(suborder_quantity) AS last_30d_qty, SUM(selling_price) AS last_30d_sales, SUM(suborder_quantity) / 30.0 AS avg_daily_sales_30d FROM sales WHERE order_date >= CURRENT_DATE - 30 GROUP BY 1 ), cogs_base AS ( SELECT sku_group, cogs FROM snitch_db.maplemonk.meta_mapping_cogs_sku ), category_avg_cogs AS ( SELECT s.category, AVG(c.cogs) AS avg_category_cogs FROM sales s JOIN cogs_base c ON s.sku_group = c.sku_group WHERE c.cogs IS NOT NULL GROUP BY 1 ), overall_avg_cogs AS ( SELECT AVG(cogs) AS avg_overall_cogs FROM cogs_base WHERE cogs IS NOT NULL ), sku_base AS ( SELECT DISTINCT sku_group FROM sales_agg UNION SELECT DISTINCT sku_group FROM inv ), final_base AS ( SELECT b.sku_group, sa.order_date, sa.marketplace_mapped, sa.branch_code, sa.source, sa.order_name, sa.account_name, sa.order_timestamp, sa.mrp, sa.dispatch_date, sa.category, COALESCE(sa.total_qty, 0) AS total_qty, COALESCE(sa.total_sales_value, 0) AS total_sales_value, COALESCE(i.inventory_in_hand, 0) AS inventory_in_hand, COALESCE(i.carton_stock, 0) AS carton_stock, COALESCE(s30.last_30d_qty, 0) AS last_30d_qty, COALESCE(s30.last_30d_sales, 0) AS last_30d_sales, COALESCE(s30.avg_daily_sales_30d, 0) AS avg_daily_sales_30d, cb.cogs AS sku_level_cogs, ca.avg_category_cogs, oa.avg_overall_cogs, purchase_date, COALESCE( cb.cogs, ca.avg_category_cogs, CASE WHEN LOWER(sa.category) = \'perfumes\' THEN 150 END, oa.avg_overall_cogs ) AS cogs_per_unit, ROW_NUMBER() OVER ( PARTITION BY b.sku_group ORDER BY sa.order_date DESC, sa.order_timestamp DESC ) AS rn FROM sku_base b LEFT JOIN sales_agg sa ON b.sku_group = sa.sku_group LEFT JOIN inv i ON b.sku_group = i.sku_group LEFT JOIN sales_30d s30 ON b.sku_group = s30.sku_group LEFT JOIN cogs_base cb ON b.sku_group = cb.sku_group LEFT JOIN category_avg_cogs ca ON sa.category = ca.category CROSS JOIN overall_avg_cogs oa ) SELECT sku_group, CASE WHEN rn = 1 THEN inventory_in_hand ELSE 0 END AS inventory_in_hand, CASE WHEN rn = 1 THEN carton_stock ELSE 0 END AS carton_stock, order_date, marketplace_mapped, branch_code, source, order_name, account_name, order_timestamp, total_qty, total_sales_value, mrp, dispatch_date, case when sku_group like \'4MSS%\' then \'SHIRTS\' when sku_group like \'4MST%\' then \'T-SHIRTS\' when sku_group like \'4MSR%\' then \'TROUSERS\' when sku_group like \'4MVK%\' then \'Denim\' when sku_group like \'4TR%\' then \'TROUSERS\' when sku_group like \'4MSD%\' then \'Denim\' when sku_group like \'4MSR%\' then \'TROUSERS\' when sku_group like \'4MSIW%\' then \'SWEATERS\' when sku_group like \'4MSK%\' then \'JACKETS\' when sku_group like \'4MSO%\' then \'OVERSHIRT\' when sku_group like \'4MSFR%\' then \'PERFUMES\' when sku_group like \'4MSC%\' then \'TROUSERS\' when sku_group like \'4MTP%\' then \'TROUSERS\' else category end as category, purchase_date, sku_level_cogs, avg_category_cogs, avg_overall_cogs, cogs_per_unit, CASE WHEN total_qty > 0 AND cogs_per_unit IS NOT NULL THEN total_qty * cogs_per_unit ELSE 0 END AS total_cogs, CASE WHEN total_sales_value > 0 AND cogs_per_unit IS NOT NULL THEN total_sales_value - (total_qty * cogs_per_unit) ELSE NULL END AS gross_margin, CASE WHEN total_sales_value > 0 AND cogs_per_unit IS NOT NULL THEN ((total_sales_value - (total_qty * cogs_per_unit)) / total_sales_value) * 100 ELSE NULL END AS gross_margin_pct, CASE WHEN rn = 1 THEN last_30d_qty ELSE 0 END AS last_30d_qty, CASE WHEN rn = 1 THEN last_30d_sales ELSE 0 END AS last_30d_sales, CASE WHEN rn = 1 AND avg_daily_sales_30d > 0 THEN inventory_in_hand / avg_daily_sales_30d ELSE NULL END AS doi, CASE WHEN rn = 1 AND (last_30d_qty + inventory_in_hand) > 0 THEN (last_30d_qty / (last_30d_qty + inventory_in_hand)) * 100 ELSE NULL END AS str_pct, CASE WHEN purchase_date IS NULL THEN \'Unknown\' WHEN DATEDIFF(day, TO_DATE(purchase_date,\'DD/MM/YYYY\'), CURRENT_DATE) < 30 THEN \'<30 days\' WHEN DATEDIFF(day, TO_DATE(purchase_date,\'DD/MM/YYYY\'), CURRENT_DATE) < 90 THEN \'30-89 days\' WHEN DATEDIFF(day, TO_DATE(purchase_date,\'DD/MM/YYYY\'), CURRENT_DATE) < 180 THEN \'90-179 days\' WHEN DATEDIFF(day, TO_DATE(purchase_date,\'DD/MM/YYYY\'), CURRENT_DATE) < 270 THEN \'180-269 days\' ELSE \'270+ days\' END AS ageing_bucket, CASE WHEN purchase_date IS NULL THEN 0 WHEN DATEDIFF(day, TO_DATE(purchase_date,\'DD/MM/YYYY\'), CURRENT_DATE) < 30 THEN 1 WHEN DATEDIFF(day, TO_DATE(purchase_date,\'DD/MM/YYYY\'), CURRENT_DATE) < 90 THEN 2 WHEN DATEDIFF(day, TO_DATE(purchase_date,\'DD/MM/YYYY\'), CURRENT_DATE) < 180 THEN 3 WHEN DATEDIFF(day, TO_DATE(purchase_date,\'DD/MM/YYYY\'), CURRENT_DATE) < 270 THEN 4 ELSE 5 END AS ageing_bucket_order FROM final_base;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            